#include "translator.hpp"
#include <windows.h>
#include <winhttp.h>
#include <vector>
#include <algorithm>
#include <cctype>
#pragma comment(lib,"winhttp.lib")
namespace {
std::wstring Widen(const std::string& s){if(s.empty())return {};int n=MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0);std::wstring w(n,L'\0');if(n)MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),w.data(),n);return w;}
std::string JsonEscape(const std::string& s){std::string o;for(unsigned char c:s){switch(c){case '"':o+="\\\"";break;case '\\':o+="\\\\";break;case '\n':o+="\\n";break;case '\r':o+="\\r";break;case '\t':o+="\\t";break;default:if(c>=0x20)o+=(char)c;}}return o;}
std::string UrlEncode(const std::string& s){static const char*h="0123456789ABCDEF";std::string o;for(unsigned char c:s){if(std::isalnum(c)||c=='-'||c=='_'||c=='.'||c=='~')o+=(char)c;else{o+='%';o+=h[c>>4];o+=h[c&15];}}return o;}
bool Http(const wchar_t* host,const wchar_t* path,const std::wstring& method,const std::wstring& headers,const std::string& body,std::string& response,DWORD& status){HINTERNET ses=WinHttpOpen(L"LilzyTranslator/ASI-R3",WINHTTP_ACCESS_TYPE_AUTOMATIC_PROXY,WINHTTP_NO_PROXY_NAME,WINHTTP_NO_PROXY_BYPASS,0);if(!ses)return false;WinHttpSetTimeouts(ses,8000,8000,15000,30000);HINTERNET con=WinHttpConnect(ses,host,INTERNET_DEFAULT_HTTPS_PORT,0);if(!con){WinHttpCloseHandle(ses);return false;}HINTERNET req=WinHttpOpenRequest(con,method.c_str(),path,nullptr,WINHTTP_NO_REFERER,WINHTTP_DEFAULT_ACCEPT_TYPES,WINHTTP_FLAG_SECURE);if(!req){WinHttpCloseHandle(con);WinHttpCloseHandle(ses);return false;}BOOL ok=WinHttpSendRequest(req,headers.empty()?WINHTTP_NO_ADDITIONAL_HEADERS:headers.c_str(),headers.empty()?0:(DWORD)-1,body.empty()?WINHTTP_NO_REQUEST_DATA:(LPVOID)body.data(),(DWORD)body.size(),(DWORD)body.size(),0)&&WinHttpReceiveResponse(req,nullptr);status=0;DWORD sz=sizeof(status);if(ok)WinHttpQueryHeaders(req,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,WINHTTP_HEADER_NAME_BY_INDEX,&status,&sz,WINHTTP_NO_HEADER_INDEX);if(ok){DWORD avail=0;do{avail=0;if(!WinHttpQueryDataAvailable(req,&avail)||!avail)break;std::vector<char>b(avail);DWORD got=0;if(!WinHttpReadData(req,b.data(),avail,&got))break;response.append(b.data(),got);}while(avail);}WinHttpCloseHandle(req);WinHttpCloseHandle(con);WinHttpCloseHandle(ses);return ok==TRUE;}
bool JsonStringAfter(const std::string& j,const std::string& key,std::string& out){size_t p=j.find(key);if(p==j.npos)return false;p=j.find(':',p+key.size());if(p==j.npos)return false;p=j.find('"',p+1);if(p==j.npos)return false;++p;for(;p<j.size();++p){char c=j[p];if(c=='"')return true;if(c=='\\'&&p+1<j.size()){char e=j[++p];switch(e){case 'n':out+='\n';break;case 'r':out+='\r';break;case 't':out+='\t';break;case 'b':out+='\b';break;case 'f':out+='\f';break;case 'u':if(p+4<j.size())p+=4;out+='?';break;default:out+=e;}}else out+=c;}return false;}
std::string MoodInstruction(const std::string&m){if(m=="friendly")return "Use a warm and friendly tone.";if(m=="aggressive")return "Use a firm and confrontational tone.";if(m=="sarcastic")return "Use a sarcastic and ironic tone.";if(m=="playful")return "Use a playful and humorous tone.";if(m=="cold")return "Use a cold and emotionally distant tone.";if(m=="professional")return "Use a professional and respectful tone.";if(m=="romantic")return "Use a gentle and affectionate tone.";return "Use a neutral and balanced tone.";}
std::string StyleInstruction(const std::string&s){std::string tail="";if(s=="formal")tail="Translate into clean formal English. No slang.";else if(s=="los_angeles")tail="Translate using West Coast LA street English. Use slang naturally (homie, cuh, finna, trippin'). Do not force slang.";else if(s=="latino")tail="Translate using Chicano street English. Use slang naturally (ese, vato, carnal, foo).";else if(s=="bay_area")tail="Translate using Bay Area street English. Use slang naturally (hella, bruh, mobbin').";else if(s=="chicago")tail="Translate using Chicago street English. Use slang naturally (folks, gang, finna, shorty).";else if(s=="new_york")tail="Translate using New York street English. Use slang naturally (deadass, son, mad, buggin').";else if(s=="atlanta")tail="Translate using Atlanta street English. Use slang naturally (shawty, twin, finna, fr).";else if(s=="houston")tail="Translate using Houston street English. Use slang naturally (fam, mane, trill, finna).";else if(s=="miami")tail="Translate using Miami street English. Use slang naturally (dawg, bro, fam, jit).";else if(s=="british_urban")tail="Translate using London Urban English. Use ONLY UK slang (bruv, fam, mandem, innit, wagwan). No American slang.";else if(s=="asian_american")tail="Translate using Asian-American street English. Use slang naturally (bro, lowkey, fr, no cap, bet).";else tail="Translate into natural casual English. Light slang allowed (bro, yeah, gonna, kinda).";return "You are an RP translator.\nRules:\n- keep meaning exactly the same\n- output ONLY the translation\n- no explanation\n- no extra sentences\n- natural RP dialogue style\n- do not repeat or paraphrase\n- keep it short and realistic\n\n"+tail;}
bool Groq(const Config&c,const std::string&input,bool isMe,std::string&out,std::string&err){if(c.apiKey.empty()){err="Groq API key belum diatur. Pakai /setkey <key>.";return false;}std::string prompt;if(isMe)prompt="/ME RULE:\n/ OUTPUT ONLY RAW RP ACTION\n/ NO SUBJECT (no names, no aku, no dia)\n/ NO EXPLANATION\n/ NO INTRODUCTION OR EXTRA TEXT\n/ PRESERVE EVERY ACTION AND DETAIL FROM THE ORIGINAL\n/ NEVER OMIT, SKIP, OR SUMMARIZE ANY ACTION\n/ PRESERVE OBJECTS, BODY PARTS, LOCATIONS, AND ACTION SEQUENCES\n/ PRESERVE THE EXACT INTENDED MEANING\n/ TRANSLATE SLANG AND BROKEN GRAMMAR BY CONTEXT\n/ DO NOT INVENT ACTIONS OR DETAILS\n/ RESULT MUST BE A COMPLETE RP ACTION PHRASE\n/ SERVER HANDLES PLAYER NAME AUTOMATICALLY\n\n";prompt+=StyleInstruction(c.preset)+"\n\nMOOD:\n"+MoodInstruction(c.mood)+"\nMood changes tone only. Preserve the original meaning. Never add information, slang, or emotions that are not supported by the source text.\n\nText:\n"+input;
std::string body="{\"model\":\""+JsonEscape(c.model)+"\",\"temperature\":0.7,\"messages\":[{\"role\":\"user\",\"content\":\""+JsonEscape(prompt)+"\"}]}";std::string resp;DWORD status=0;std::wstring h=L"Content-Type: application/json\r\nAuthorization: Bearer "+Widen(c.apiKey)+L"\r\n";if(!Http(L"api.groq.com",L"/openai/v1/chat/completions",L"POST",h,body,resp,status)){err="HTTP request Groq gagal.";return false;}if(status<200||status>=300){err="Groq HTTP "+std::to_string(status)+": "+resp.substr(0,220);return false;}if(!JsonStringAfter(resp,"\"content\"",out)){err="Respons Groq tidak terbaca.";return false;}return true;}
bool MyMemory(const std::string&input,std::string&out,std::string&err){std::string path="/get?q="+UrlEncode(input)+"&langpair=id%7Cen";std::string resp;DWORD status=0;if(!Http(L"api.mymemory.translated.net",Widen(path).c_str(),L"GET",L"Accept: application/json\r\n",{},resp,status)){err="HTTP request MyMemory gagal.";return false;}if(status<200||status>=300){err="MyMemory HTTP "+std::to_string(status);return false;}if(!JsonStringAfter(resp,"\"translatedText\"",out)){err="Respons MyMemory tidak terbaca.";return false;}auto replace=[&](const std::string&a,const std::string&b){size_t p=0;while((p=out.find(a,p))!=std::string::npos){out.replace(p,a.size(),b);p+=b.size();}};replace("&quot;","\"");replace("&#39;","'");replace("&amp;","&");replace("&lt;","<");replace("&gt;",">");return true;}
}
bool TranslateText(const Config&cfg,const std::string&text,std::string&output,std::string&error){if(text.empty()){error="Teks kosong.";return false;}std::string input=text;bool me=false;if(input.size()>=4&&_strnicmp(input.c_str(),"/me ",4)==0){input.erase(0,4);me=true;}else if(input.size()>=4&&_strnicmp(input.c_str(),"/do ",4)==0){input.erase(0,4);}if(cfg.provider=="groq"){if(!Groq(cfg,input,me,output,error))return false;}else{if(!MyMemory(input,output,error))return false;}output.erase(std::remove(output.begin(),output.end(),'\r'),output.end());std::replace(output.begin(),output.end(),'\n',' ');while(!output.empty()&&std::isspace((unsigned char)output.back()))output.pop_back();size_t p=0;while(p<output.size()&&std::isspace((unsigned char)output[p]))++p;if(p)output.erase(0,p);if(text.size()>=4&&_strnicmp(text.c_str(),"/me ",4)==0)output="/me "+output;else if(text.size()>=4&&_strnicmp(text.c_str(),"/do ",4)==0)output="/do "+output;return !output.empty();}
bool CopyUnicodeText(const std::string&utf8){if(!OpenClipboard(nullptr))return false;EmptyClipboard();int n=MultiByteToWideChar(CP_UTF8,0,utf8.c_str(),-1,nullptr,0);if(n<=0){CloseClipboard();return false;}HGLOBAL h=GlobalAlloc(GMEM_MOVEABLE,n*sizeof(wchar_t));if(!h){CloseClipboard();return false;}wchar_t*p=(wchar_t*)GlobalLock(h);if(!p){GlobalFree(h);CloseClipboard();return false;}MultiByteToWideChar(CP_UTF8,0,utf8.c_str(),-1,p,n);GlobalUnlock(h);if(!SetClipboardData(CF_UNICODETEXT,h)){GlobalFree(h);CloseClipboard();return false;}CloseClipboard();return true;}
